parameters.query:
SELECT station_code, district, water_body_name, sampling_date, bod, dissolved_oxygen, fecal_coliform, non_compliant
FROM dw_water_quality_clean
WHERE sampling_date >= (SELECT MAX(sampling_date) - 14 FROM dw_water_quality_clean);

parameters.jsCode:
const rows = $input.all().map(i => i.json).map(r => ({
  ...r,
  d: new Date(r.sampling_date),
  bod: r.bod === null ? null : Number(r.bod),
  dissolved_oxygen: r.dissolved_oxygen === null ? null : Number(r.dissolved_oxygen),
  fecal_coliform: r.fecal_coliform === null ? null : Number(r.fecal_coliform),
}));
// ---- thresholds (edit here) ----
const T = { ncRiseThreshold: 5, bodLimit: 3, doMin: 5, fcLimit: 500, consecutiveDays: 3 };
const DAY = 86400000;
const maxD = new Date(Math.max(...rows.map(r => r.d)));
const thisWeek = rows.filter(r => r.d > new Date(maxD - 7 * DAY));
const prevWeek = rows.filter(r => r.d <= new Date(maxD - 7 * DAY) && r.d > new Date(maxD - 14 * DAY));
const pctNC = a => { const c = a.filter(r => r.non_compliant !== null); return c.length ? 100 * c.filter(r => r.non_compliant === true).length / c.length : null; };
const nowPct = pctNC(thisWeek), prevPct = pctNC(prevWeek);
const alerts = [], metrics = { as_of: maxD.toISOString().slice(0, 10), pct_non_compliant_this_week: nowPct === null ? null : +nowPct.toFixed(1), pct_non_compliant_prev_week: prevPct === null ? null : +prevPct.toFixed(1) };
// 1) non-compliance rise
if (nowPct !== null && prevPct !== null && nowPct - prevPct >= T.ncRiseThreshold) alerts.push(`Non-compliant samples rose from ${prevPct.toFixed(1)}% to ${nowPct.toFixed(1)}% week on week`);
// 2) BOD above limit by district
const byD = {}; thisWeek.filter(r => r.bod !== null).forEach(r => (byD[r.district] = byD[r.district] || []).push(r.bod));
const bodDistricts = Object.entries(byD).map(([district, v]) => ({ district, avg_bod: +(v.reduce((a, b) => a + b, 0) / v.length).toFixed(1), n: v.length })).filter(x => x.avg_bod > T.bodLimit).sort((a, b) => b.avg_bod - a.avg_bod);
if (bodDistricts.length) alerts.push(`${bodDistricts.length} districts have average BOD above ${T.bodLimit} mg/L`);
metrics.top_bod_districts = bodDistricts.slice(0, 5);
// 3) low dissolved oxygen
const lowDO = thisWeek.filter(r => r.dissolved_oxygen !== null && r.dissolved_oxygen < T.doMin);
if (lowDO.length) alerts.push(`${lowDO.length} stations have dissolved oxygen below ${T.doMin} mg/L`);
metrics.lowest_do_stations = lowDO.sort((a, b) => a.dissolved_oxygen - b.dissolved_oxygen).slice(0, 5).map(r => ({ station: r.station_code, district: r.district, water_body: r.water_body_name, do: r.dissolved_oxygen, bod: r.bod }));
// 4) fecal coliform above limit
const fc = thisWeek.filter(r => r.fecal_coliform !== null && r.fecal_coliform > T.fcLimit);
if (fc.length) alerts.push(`${fc.length} samples exceed fecal coliform limit of ${T.fcLimit}`);
metrics.fecal_coliform_exceedances = fc.slice(0, 5).map(r => ({ station: r.station_code, district: r.district, fc: r.fecal_coliform, do: r.dissolved_oxygen }));
// 5) same station non-compliant on N consecutive days
const byS = {}; rows.forEach(r => (byS[r.station_code] = byS[r.station_code] || []).push(r));
const repeat = [];
for (const [st, rs] of Object.entries(byS)) {
  const days = [...new Set(rs.filter(r => r.non_compliant === true).map(r => r.d.toISOString().slice(0, 10)))].sort();
  let run = 1;
  for (let i = 1; i < days.length; i++) { run = (new Date(days[i]) - new Date(days[i - 1])) === DAY ? run + 1 : 1; if (run >= T.consecutiveDays) { repeat.push({ station: st, district: rs[0].district }); break; } }
}
if (repeat.length) alerts.push(`${repeat.length} stations unsafe for ${T.consecutiveDays}+ consecutive days`);
metrics.repeat_unsafe_stations = repeat.slice(0, 5);
return [{ json: { alert: alerts.length > 0, alerts, metrics } }];

const a = $input.first().json;
const system = "You are an environmental data analyst supporting the Maharashtra Pollution Control Board. Use ONLY the numbers provided. Never invent figures. Present causes as 'possible causes', not facts. Write in plain English for regulators and public health officials. Be concise.";
const prompt = `Rule-based checks flagged these water quality risks (as of ${a.metrics.as_of}):
${a.alerts.map(x => '- ' + x).join('\n')}

Supporting data (JSON):
${JSON.stringify(a.metrics)}

Write an alert of at most 150 words in this format:
WATER QUALITY ALERT
What happened: (use the numbers above)
Possible causes: (2 to 3, clearly hedged, based on the data such as industrial effluent or untreated sewage)
Suggested regulatory action: (2 concrete steps, e.g. inspection, effluent source investigation, advisory)
Do not add facts that are not in the data.`;
return [{ json: { system, prompt } }];
